ev("aisale24","2024-08-01",A,"판촉","8월 '삼성전자 AI 세일 페스타'를 처음 열었다(세일 페스타는 그동안 1월에 열림). 삼성닷컴에서 매주 신제품을 쇼킹 프라이스 최대 50%로 판매하고, AI 패키지는 2개 이상 구매 시 최대 30만 원 혜택을 준다고 스마트투데이가 전했다.",["st_aisale24"],nm="2024 AI 세일 페스타(8월)",benefit="즉시할인: 쇼킹 프라이스 최대 50%; 포인트: 언급 없음; 카드: 언급 없음; 패키지: AI 패키지 2개 이상 구매 시 최대 30만 원; 기타: 없음",period_start="2024-08",channel="삼성닷컴",imp=3,flags=["AI 패키지 30만 원의 적용 단위(품목당·합계)는 기사 확인 필요","8월 개최가 반복되는지 2025년 이후 기록 없음"])
ev("ksf24","2024-11-01",A,"판촉","2024 코리아세일페스타에 참여해 11월 한 달간 15개 품목 148개 제품을 판매했다. 일부 신제품 최대 49% 할인, 스마트 패키지 최대 495만 원 혜택을 내걸었고, 올해 처음 AI 제품 2개 이상 구매 시 최대 5만 원 추가 할인을 스마트 패키지와 중복 적용하게 했다.",["st_ksf24"],nm="2024 코리아세일페스타",benefit="즉시할인: 일부 신제품 최대 49%; 포인트: 언급 없음; 카드: 언급 없음; 패키지: 스마트 패키지 최대 495만 원, AI 패키지 최대 5만 원 추가; 기타: 없음",rec="정기",period_start="2024-11-01",period_end="2024-11-30",imp=3,flags=["으뜸효율·카드·판매 채널은 기사에 없음"])
ev("sale25","2024-12-16",A,"판촉","2025 세일 페스타를 2024년 12월 16일부터 2025년 2월 10일까지 열었다. 쇼킹프라이스를 매주 월요일 공개하고 최대 50% 할인했으며, AI 구독클럽 가입 시 최대 12개월 구독료를 포인트로 줬다.",["st_sale25"],nm="2025 세일 페스타(5회)",benefit="즉시할인: 쇼킹프라이스 매주 월요일, 최대 50%; 포인트: AI 구독클럽 최대 12개월 구독료 포인트; 카드: 언급 없음; 패키지: 언급 없음; 기타: 없음",rec="정기",period_start="2024-12-16",period_end="2025-02-10",imp=3,flags=["시작이 전년 12월이어서 2025년 1월 개시 해와 다름"])
